(5529422, 799033, 30982, '<td valign="top">I hope those are fake and you didn''t steal some mama''s babies for this shot!  Toning is nicely suited.</td>', 'I hope those are fake and you didn''t steal some mama''s babies for this shot!  Toning is nicely suited.', '2009-06-15 13:56:19.000000', NULL, 1),
(5529423, 799191, 30982, '<td valign="top">Nicely composed with good light, good detail.  Not "in your face" sharp, which is quite nice here.</td>', 'Nicely composed with good light, good detail.  Not "in your face" sharp, which is quite nice here.', '2009-06-15 13:56:52.000000', NULL, 1),
(5529425, 798738, 101678, '<td valign="top">Here it is!  I''d give it a 9!  I really like this.  The velvet textures, the wonderful treatment.  All very good stuff.</td>', 'Here it is!  I''d give it a 9!  I really like this.  The velvet textures, the wonderful treatment.  All very good stuff.', '2009-06-15 13:57:27.000000', NULL, 1),
