(5534179, 799226, 42495, '<td valign="top">Interesting concept, but the lack of contrast doesn''t pull me in.</td>', 'Interesting concept, but the lack of contrast doesn''t pull me in.', '2009-06-17 22:51:07.000000', NULL, 1),
(5534183, 799237, 51747, '<td valign="top">It looks like they had to use this door for it''s intended purpose. Too bad. I like your choice of color for this.</td>', 'It looks like they had to use this door for it''s intended purpose. Too bad. I like your choice of color for this.', '2009-06-17 22:54:51.000000', NULL, 1),
