(5534780, 799146, 65234, '<td valign="top">This one says old, tired, and not as beautiful as it used to be.  But maybe a cherished souvenir of a beautiful memory.</td>', 'This one says old, tired, and not as beautiful as it used to be.  But maybe a cherished souvenir of a beautiful memory.', '2009-06-18 10:52:02.000000', NULL, 1),
(5534781, 799334, 65234, '<td valign="top">I can almost feel the sun pulling clouds after it into twilight.</td>', 'I can almost feel the sun pulling clouds after it into twilight.', '2009-06-18 10:52:48.000000', NULL, 1),
