(5535340, 798799, 15711, '<td valign="top">Really nice kitty portrait. Great lighting and DOF.</td>', 'Really nice kitty portrait. Great lighting and DOF.', '2009-06-18 16:29:58.000000', NULL, 1),
(5535345, 798986, 15711, '<td valign="top">This is pure deliciousness.  I usually don''t like over saturation in a duotone but man - this is almost something I can taste and smell. Nice. Bumping up.</td>', 'This is pure deliciousness.  I usually don''t like over saturation in a duotone but man - this is almost something I can taste and smell. Nice. Bumping up.', '2009-06-18 16:30:24.000000', NULL, 1),
(5535394, 799453, 88204, '<td valign="top">Wonderful emphasis on the eyes! Nice use of shallow depth of field. 9</td>', 'Wonderful emphasis on the eyes! Nice use of shallow depth of field. 9', '2009-06-18 16:57:38.000000', NULL, 1),
(5535396, 798174, 88204, '<td valign="top">Wonderful environmental portrait. I would love to see a second image with this that is more of a close up on the face... looks like lots of character (of course you can''t submit two images, but that would be a nice presentation elsewhere).</td>', 'Wonderful environmental portrait. I would love to see a second image with this that is more of a close up on the face... looks like lots of character (of course you can''t submit two images, but that would be a nice presentation elsewhere).', '2009-06-18 16:59:16.000000', NULL, 1),
(5535399, 799112, 88204, '<td valign="top">Neat shot! I''m not sure I get the watercolor effect but still interesting.</td>', 'Neat shot! I''m not sure I get the watercolor effect but still interesting.', '2009-06-18 17:00:31.000000', NULL, 1),
(5535402, 798738, 88204, '<td valign="top">Beautiful exposure and shallow DoF.</td>', 'Beautiful exposure and shallow DoF.', '2009-06-18 17:01:09.000000', NULL, 1),
(5535422, 799326, 88204, '<td valign="top">Beautiful exposure and tones.</td>', 'Beautiful exposure and tones.', '2009-06-18 17:11:41.000000', NULL, 1),
(5535425, 798511, 88204, '<td valign="top">Hmmm... not sure what to look at here. The focus seems to be on the chairs and table although I''m more curious about the dog.</td>', 'Hmmm... not sure what to look at here. The focus seems to be on the chairs and table although I''m more curious about the dog.', '2009-06-18 17:13:09.000000', NULL, 1),
(5535503, 799453, 52500, '<td valign="top">Great portrait.  Really nice tones, too.  I''ll bet I''m not the only one that thinks the eyes are just a tad overdone.</td>', 'Great portrait.  Really nice tones, too.  I''ll bet I''m not the only one that thinks the eyes are just a tad overdone.', '2009-06-18 18:26:42.000000', NULL, 1),
(5535535, 798702, 9509, '<td valign="top">Lovely</td>', 'Lovely', '2009-06-18 19:10:41.000000', NULL, 1),
(5535538, 799225, 9509, '<td valign="top">LOL...I love this image</td>', 'LOL...I love this image', '2009-06-18 19:12:08.000000', NULL, 1),
(5535566, 799112, 52130, '<td valign="top">the quality looks very poor and I don''t really see much of a composition</td>', 'the quality looks very poor and I don''t really see much of a composition', '2009-06-18 19:33:33.000000', NULL, 1),
(5535568, 799370, 52130, '<td valign="top">I wish the hood was in sharper focus and I don''t consider this to be a duotone</td>', 'I wish the hood was in sharper focus and I don''t consider this to be a duotone', '2009-06-18 19:34:14.000000', NULL, 1),
(5535569, 798167, 52130, '<td valign="top">too much going on here, tricky light and also not a duotone</td>', 'too much going on here, tricky light and also not a duotone', '2009-06-18 19:34:42.000000', NULL, 1),
(5535571, 799078, 52130, '<td valign="top">I see sepia, black, white, and red. That does not fit the definition of a duotone and I also feel like you are just snapping a photo of someone else''s work with very little attempt to make it artistically your own</td>', 'I see sepia, black, white, and red. That does not fit the definition of a duotone and I also feel like you are just snapping a photo of someone else''s work with very little attempt to make it artistically your own', '2009-06-18 19:36:20.000000', NULL, 1),
(5535573, 799331, 52130, '<td valign="top">too much motion blur, and no real composition to speak of. Also not a dutone</td>', 'too much motion blur, and no real composition to speak of. Also not a dutone', '2009-06-18 19:36:57.000000', NULL, 1),
(5535578, 799091, 52130, '<td valign="top">I find it funny that you felt it was appropriate to show a middle finger but rewrite "fuck" as "fcuk". If you''re gonna be ballsy, at least go all balls out instead of half way. Also, I can tell this is a non-converted color image, but I understand your view on this being a duotone. Close, but not quite there I''m afraid.</td>', 'I find it funny that you felt it was appropriate to show a middle finger but rewrite "fuck" as "fcuk". If you''re gonna be ballsy, at least go all balls out instead of half way. Also, I can tell this is a non-converted color image, but I understand your view on this being a duotone. Close, but not quite there I''m afraid.', '2009-06-18 19:39:37.000000', NULL, 1),
(5535580, 799226, 52130, '<td valign="top">this is a good image with really bad processing. The hazy appearance of this really detracts from the strong composition. It seems as if this is only an image of midtones which makes it very difficult for me to look at. But congratulations because this IS a duotone, although I must say that I''m not a big fan of the color, which reminds me of what the floor of the cow''s stall must look like XP bumping you up a couple points though.</td>', 'this is a good image with really bad processing. The hazy appearance of this really detracts from the strong composition. It seems as if this is only an image of midtones which makes it very difficult for me to look at. But congratulations because this IS a duotone, although I must say that I''m not a big fan of the color, which reminds me of what the floor of the cow''s stall must look like XP bumping you up a couple points though.', '2009-06-18 19:42:55.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5535584, 799192, 52130, '<td valign="top">this could have been a good image if the lighting was better. Also, the lower perspective is not very flattering and makes the chin and lower neck appear larger.</td>', 'this could have been a good image if the lighting was better. Also, the lower perspective is not very flattering and makes the chin and lower neck appear larger.', '2009-06-18 19:44:07.000000', NULL, 1),
